<?php
$pdo=db();$q=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,s.status FROM guardian_user_links l JOIN student_guardians g ON g.id=l.guardian_id AND g.consent_status='Granted' JOIN students s ON s.id=g.student_id WHERE l.user_id=:user ORDER BY s.last_name,s.first_name");$q->execute(['user'=>$user['id']]);$children=$q->fetchAll();$term=$pdo->query('SELECT id,name,academic_year,starts_on,ends_on FROM school_terms WHERE is_current=1 ORDER BY academic_year DESC,term_number DESC LIMIT 1')->fetch()?:null;
?>
<section class="panel info-panel"><h2>Family portal</h2><p>These details are limited to learner records linked to your guardian account. Contact the school office if a learner is missing or these records need correction.</p></section>
<?php if(!$children): ?><section class="panel empty-state"><h2>No learner accounts are linked</h2><p>The school must verify your guardian contact and link the learner record before family information appears here.</p></section><?php else: foreach($children as $child):
 $att=['Present'=>0,'Late'=>0,'Absent'=>0,'Excused'=>0];if($term){$a=$pdo->prepare('SELECT status,COUNT(*) AS total FROM attendance WHERE student_id=:student AND attendance_date BETWEEN :start AND :end GROUP BY status');$a->execute(['student'=>$child['id'],'start'=>$term['starts_on'],'end'=>$term['ends_on']]);foreach($a->fetchAll() as $row)$att[$row['status']]=(int)$row['total'];}
 $fee=['USD'=>0.0,'ZiG'=>0.0];if($term){$f=$pdo->prepare("SELECT currency,SUM(CASE WHEN transaction_type='Payment' THEN -amount ELSE amount END) balance FROM fee_ledger WHERE student_id=:student AND term_id=:term GROUP BY currency");$f->execute(['student'=>$child['id'],'term'=>$term['id']]);foreach($f->fetchAll() as $row)$fee[$row['currency']]=(float)$row['balance'];}
 $results=[];$classId=null;$childBands=[];if($term){$c=$pdo->prepare("SELECT c.id,c.form_level FROM student_enrolments e JOIN class_groups c ON c.academic_year=e.academic_year AND c.form_level=e.form_level AND c.stream=COALESCE(e.stream,'') WHERE e.student_id=:student AND e.academic_year=:year AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start) ORDER BY e.start_date DESC,e.id DESC LIMIT 1");$c->execute(['student'=>$child['id'],'year'=>$term['academic_year'],'term_end'=>$term['ends_on'],'term_start'=>$term['starts_on']]);$enrolmentClass=$c->fetch();$classId=$enrolmentClass['id']??null;if($classId){$level=(int)$enrolmentClass['form_level']<=4?'O-Level':'A-Level';$sc=$pdo->prepare('SELECT id FROM grading_scales WHERE level=:level AND active=1 ORDER BY id DESC LIMIT 1');$sc->execute(['level'=>$level]);$scaleId=$sc->fetchColumn();if($scaleId){$bandStmt=$pdo->prepare('SELECT grade,lower_percentage,upper_percentage FROM grading_bands WHERE scale_id=:scale');$bandStmt->execute(['scale'=>$scaleId]);$childBands=$bandStmt->fetchAll();}$r=$pdo->prepare("SELECT s.subject_code,s.subject_name,SUM(CASE WHEN m.mark_status='Scored' THEN m.mark ELSE 0 END) obtained,SUM(CASE WHEN m.mark_status='Scored' THEN a.max_mark ELSE 0 END) possible,COUNT(a.id) assessments,SUM(m.mark_status IS NOT NULL) entered FROM class_subjects cs JOIN subjects s ON s.id=cs.subject_id AND s.active=1 LEFT JOIN assessments a ON a.class_id=cs.class_id AND a.subject_id=cs.subject_id AND a.term_id=:term LEFT JOIN assessment_marks m ON m.assessment_id=a.id AND m.student_id=:student WHERE cs.class_id=:class GROUP BY s.id,s.subject_code,s.subject_name ORDER BY s.subject_name");$r->execute(['term'=>$term['id'],'student'=>$child['id'],'class'=>$classId]);$results=$r->fetchAll();foreach($results as &$result){$possible=(float)$result['possible'];$result['percentage']=$possible?round((float)$result['obtained']/$possible*100,2):null;$result['grade']=null;if($result['percentage']!==null)foreach($childBands as $band)if($result['percentage']>=(float)$band['lower_percentage']&&$result['percentage']<=(float)$band['upper_percentage']){$result['grade']=$band['grade'];break;}}unset($result);}}
 $attTotal=array_sum($att);$attendanceRate=($att['Present']+$att['Late']+$att['Absent'])?round(($att['Present']+$att['Late'])/($att['Present']+$att['Late']+$att['Absent'])*100):null;
?>
<article class="panel family-card"><div class="family-card-header"><div><div class="eyebrow"><?= h($child['admission_no']) ?></div><h2><?= h($child['first_name'].' '.$child['last_name']) ?></h2><p>Form <?= (int)$child['form_level'] ?><?= $child['stream']?' · '.h($child['stream']):'' ?> · <?= h($child['status']) ?></p></div><?php if($term): ?><span class="status-pill"><?= h($term['name']) ?> <?= (int)$term['academic_year'] ?></span><?php endif; ?></div>
<div class="report-stat-grid"><div><small>Attendance recorded</small><b><?= $attTotal ?> days<?= $attendanceRate!==null?' · '.$attendanceRate.'%':'' ?></b></div><div><small>USD fees balance</small><b>$<?= number_format($fee['USD'],2) ?></b></div><div><small>ZiG fees balance</small><b>ZiG <?= number_format($fee['ZiG'],2) ?></b></div><div><small>School term</small><b><?= $term?h($term['name']):'Not set' ?></b></div></div>
<?php if($term): ?><section class="family-attendance"><h3>Attendance</h3><div><?php foreach($att as $status=>$count): ?><span><b><?= $count ?></b> <?= h($status) ?></span><?php endforeach; ?></div></section><section class="family-results"><h3>Academic progress</h3><?php if(!$classId): ?><p class="privacy-note">No class group is configured for this learner and current term yet.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Subject</th><th>Assessments entered</th><th>Marks</th><th>Percent</th><th>Grade</th></tr></thead><tbody><?php foreach($results as $result): ?><tr><td><?= h($result['subject_name']) ?></td><td><?= (int)$result['entered'] ?> / <?= (int)$result['assessments'] ?></td><td><?= (float)$result['possible']>0?number_format((float)$result['obtained'],2).' / '.number_format((float)$result['possible'],2):'—' ?></td><td><?= $result['percentage']!==null?number_format($result['percentage'],1).'%':'—' ?></td><td><?= h($result['grade']??($result['percentage']===null?'—':'No grade band')) ?></td></tr><?php endforeach; if(!$results): ?><tr><td colspan="5" class="empty-cell">No subject results are available yet.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?></section><?php else: ?><p class="privacy-note">The school has not set a current term yet.</p><?php endif; ?></article>
<?php endforeach; endif; ?>
